@import 'c/ihStyles';

.period-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: flex-start;
    gap: 12px;
    padding: 10px 16px;
}
.period-bar lightning-combobox {
    width: 200px;
}
.period-bar .days {
    width: 90px;
}
.period-bar .date {
    width: 170px;
}
.period-bar .hint {
    padding-bottom: 8px;
}
.period-bar .spacer {
    flex: 1;
}
.group-note {
    margin: 0;
    padding: 8px 16px 0;
}
.confirm {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    justify-content: flex-end;
}
